INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.slug='super-admin';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.slug IN('homepage.manage','issues.manage','discussions.moderate','content.manage','events.manage','users.manage') WHERE r.slug='administrator';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.slug IN('homepage.manage','content.manage','events.manage') WHERE r.slug='content-editor';
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.slug IN('issues.manage','discussions.moderate') WHERE r.slug='moderator';
